import * as React from "react";
import Layout from "../components/layout";
import { graphql, HeadFC, PageProps } from "gatsby";
import  data  from "../data/data.json";
import { Company } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import ImageModal, { type ImageItem } from "../components/ImageModal";
import SEO from "../components/seo";

const companyData: Company = data as unknown as Company;

type RichTextSplit = {
  visibleHtml: string;
  hiddenHtml: string;
  hasHidden: boolean;
};

const splitRichTextAfterParagraph = (
  html: string,
  paragraphCount: number
): RichTextSplit => {
  if (!html) {
    return { visibleHtml: "", hiddenHtml: "", hasHidden: false };
  }

  const paragraphRegex = /<p\b[^>]*>[\s\S]*?<\/p>/gi;
  let paragraphMatch: RegExpExecArray | null;
  let foundParagraphs = 0;
  let splitIndex = -1;

  while ((paragraphMatch = paragraphRegex.exec(html)) !== null) {
    foundParagraphs += 1;
    if (foundParagraphs === paragraphCount) {
      splitIndex = paragraphRegex.lastIndex;
      break;
    }
  }

  if (splitIndex === -1 || splitIndex >= html.length) {
    return { visibleHtml: html, hiddenHtml: "", hasHidden: false };
  }

  const hiddenHtml = html.slice(splitIndex);
  return {
    visibleHtml: html.slice(0, splitIndex),
    hiddenHtml,
    hasHidden: hiddenHtml.trim().length > 0,
  };
};

const AboutPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  const archiveBase ="/";
  const imageExtensions = ["jpg", "jpeg", "png", "webp"];
  const [modalImages, setModalImages] = React.useState<ImageItem[]>([]);
  const [pendingOpen, setPendingOpen] = React.useState(false);
  const [isSection1Open, setIsSection1Open] = React.useState(false);
  const [isSection2Open, setIsSection2Open] = React.useState(false);
  const openModalRef = React.useRef<((startIndex?: number) => void) | null>(
    null
  );
  const section1Html = String(t("aboutUs.section1.content") || "");
  const section2Html = String(t("aboutUs.section2.content") || "");
  const section1Content = React.useMemo(
    () => splitRichTextAfterParagraph(section1Html, 2),
    [section1Html]
  );
  const section2Content = React.useMemo(
    () => splitRichTextAfterParagraph(section2Html, 2),
    [section2Html]
  );

  const openSingleImage = (item: ImageItem) => {
    setModalImages([item]);
    setPendingOpen(true);
  };

  const handleRichTextClick = (event: React.MouseEvent<HTMLElement>) => {
    const target = event.target as HTMLElement;
    const anchor = target.closest("a") as HTMLAnchorElement | null;
    if (!anchor) return;

    const href = anchor.getAttribute("href");
    if (!href || !href.startsWith(archiveBase)) return;

    const normalized = href.split("?")[0].toLowerCase();
    const isImage = imageExtensions.some((ext) =>
      normalized.endsWith(`.${ext}`)
    );
    if (!isImage) return;

    event.preventDefault();
    const label = (anchor.textContent || "").trim();
    openSingleImage({
      src: href,
      alt: label || "Image",
      caption: label || undefined,
    });
  };

  React.useEffect(() => {
    if (!pendingOpen || modalImages.length === 0) return;
    if (!openModalRef.current) return;
    openModalRef.current(0);
    setPendingOpen(false);
  }, [pendingOpen, modalImages]);

  return (
    <Layout data={companyData}>
      <section>
        <ImageModal
          images={modalImages}
          trigger={(open) => {
            openModalRef.current = open;
            return null;
          }}
        />
        
        <section className="text-terracota bg-beige p-6 sm:p-12 mb-6 shadow-lg">
          <h2 className={styles.title}>{t("aboutUs.section1.title")}</h2>
          <article
            className={styles.content}
            onClick={handleRichTextClick}
          >
            <div dangerouslySetInnerHTML={{ __html: section1Content.visibleHtml }} />
            {section1Content.hasHidden && isSection1Open && (
              <div
                id="about-section1-collapsible"
                dangerouslySetInnerHTML={{ __html: section1Content.hiddenHtml }}
              />
            )}
          </article>
          {section1Content.hasHidden && (
            <button
              type="button"
              className={styles.toggleButton}
              onClick={() => setIsSection1Open((prev) => !prev)}
              aria-expanded={isSection1Open}
              aria-controls="about-section1-collapsible"
            >
              {isSection1Open ? "See less" : "Read more"}
            </button>
          )}
          <p className={styles.author}>{t("aboutUs.section1.author")}</p>
        </section>
        <section className="text-warm_ivory bg-dark_gray p-6 sm:p-12 mb-6 shadow-lg">
          <h2 className={styles.title}>{t("aboutUs.section2.title")}</h2>
          <article
            className={styles.content}
            onClick={handleRichTextClick}
          >
            <div dangerouslySetInnerHTML={{ __html: section2Content.visibleHtml }} />
            {section2Content.hasHidden && isSection2Open && (
              <div
                id="about-section2-collapsible"
                dangerouslySetInnerHTML={{ __html: section2Content.hiddenHtml }}
              />
            )}
          </article>
          {section2Content.hasHidden && (
            <button
              type="button"
              className={styles.toggleButton}
              onClick={() => setIsSection2Open((prev) => !prev)}
              aria-expanded={isSection2Open}
              aria-controls="about-section2-collapsible"
            >
              {isSection2Open ? "See less" : "Read more"}
            </button>
          )}
          <p className={styles.author}>{t("aboutUs.section2.author")}</p>
        </section>
      </section>
    </Layout>
  )
}

export default AboutPage

export const Head: HeadFC<any> = ({ data, pageContext }) => (
  <SEO
    data={companyData}
    localesData={data?.locales?.edges?.[0]?.node?.data}
    language={(pageContext as any)?.i18n?.language}
    languages={(pageContext as any)?.i18n?.languages}
    defaultLanguage={(pageContext as any)?.i18n?.defaultLanguage}
    originalPath={(pageContext as any)?.i18n?.originalPath}
    titleKey="aboutUs.metaTitle"
    descriptionKey="aboutUs.metaDescription"
    authorKey="aboutUs.metaAuthor"
    pathname="/about/"
    schemaType="ProfessionalService"
  />
);


export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;

const styles = {
  title: "h2_mobile sm:h2_desk text-center mb-6 pt-12",
  content: "body_mobile sm:body_desk mb-3",
  toggleButton:
    "body_mobile sm:body_desk underline decoration-current underline-offset-2 mb-6",
  author: "h3_mobile sm:h3_desk flex justify-end"
}
